import{z as i,x as s,o as e,c as l,q as A,j as B,D as a,d as r,s as o,S as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"外汇干预","description":"","frontmatter":{"title":"外汇干预","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/if-fx-intervention.md","filePath":"econ/if-fx-intervention.md","lastUpdated":1791063341000}'),d={name:"econ/if-fx-intervention.md"};function p(m,E,f,_,c,D){const n=s("Mermaid");return e(),l("div",null,[E[2]||(E[2]=A('<h1 id="外汇干预" tabindex="-1">外汇干预 <a class="header-anchor" href="#外汇干预" aria-label="Permalink to &quot;外汇干预&quot;">​</a></h1><div class="epigraph"><p>冲销式干预不直接给汇率定价，它是在私人中介缺位时替市场吸收流量；有效与否，取决于能否改变私人部门的币种敞口或预期路径。</p><footer>—— 据 Dominguez and Frankel 1993；Sarno and Taylor, JEL 2001；Friedman 1953 整理</footer></div><p><a href="/econ/if-capital-flow-drivers">上一课</a>把驱动收在推拉交互上：全球推力经资产负债表打出骤停与涌入。本课转政策侧，先问价格工具。主干<a href="/econ/fx-intervention-reserves">外汇干预与储备</a>已经钉了怕浮动、冲销会计与储备需求；本课的缺口是干预<strong>怎么起作用</strong>：三条渠道各在什么条件下承重、协调干预能成什么事后退成什么、以及守水平与降波动这两种目标为什么命运不同。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>在完全替代加理性预期的世界里，冲销式干预是空操作：央行用本币换外币再冲销回笼，私人部门的币种敞口不变，UIP 定价，汇率纹丝不动。可记录里央行们在干预：日本财务省、瑞士国民银行、各新兴市场央行，规模以千亿计。矛盾不在「央行非理性」，而在教科书前提——<a href="/econ/if-fx-risk-premia">第一课</a>刚量过：风险溢价真实存在且随中介容量大幅波动，完全替代不成立。溢价在，干预才有杠杆；缺口是把这个杠杆写成可操作的渠道清单。</p><p><span class="marginnote">「冲销式干预」拆开看：央行先在外汇市场用本币买外币，按理本币供给会变多，于是再到债券市场卖出本币债，把多发的钱如数收回。「冲销」冲掉的是对国内货币总量的影响——操作前后钱的总数不变，变的只是私人部门手里的币种构成。</span></p>',6)),(e(),B(t,null,{default:a(()=>[o(n,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%A4%AE%E8%A1%8C%E4%B9%B0%E5%A4%96%E6%B1%87%E5%B9%B6%E5%86%B2%E9%94%80%22%5D%20--%3E%20Q%7B%22%E8%B5%84%E4%BA%A7%E6%98%AF%E5%90%A6%E5%AE%8C%E5%85%A8%E6%9B%BF%E4%BB%A3%22%7D%0A%20%20Q%20--%3E%7C%22%E5%AE%8C%E5%85%A8%E6%9B%BF%E4%BB%A3%22%7C%20SAME%5B%22%E7%A7%81%E4%BA%BA%E5%B8%81%E7%A7%8D%E6%95%9E%E5%8F%A3%E4%B8%8D%E5%8F%98%22%5D%0A%20%20SAME%20--%3E%20NOP%5B%22UIP%20%E5%AE%9A%E4%BB%B7%3A%20%E6%B1%87%E7%8E%87%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20Q%20--%3E%7C%22%E4%B8%8D%E5%AE%8C%E5%85%A8%E6%9B%BF%E4%BB%A3%22%7C%20COMP%5B%22%E7%A7%81%E4%BA%BA%E8%A2%AB%E8%BF%AB%E6%94%B9%E6%8C%81%E5%B8%81%E7%A7%8D%E6%9E%84%E6%88%90%22%5D%0A%20%20COMP%20--%3E%20PREM%5B%22%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%E8%A2%AB%E6%8C%AA%E5%8A%A8%22%5D%0A%20%20PREM%20--%3E%20MOVE%5B%22%E6%B1%87%E7%8E%87%E5%8F%AF%E8%A2%AB%E5%BD%B1%E5%93%8D%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>渠道分三条，各自承重条件不同。<strong>组合平衡</strong>：外汇资产与本币资产不完全替代，干预改变私人部门被迫持有的币种构成，动的正是第一课量过的溢价——渠道强时，小规模也能挪价；弱时，万亿储备只是池水。<strong>信号</strong>：干预披露央行对未来政策路径的信息，外汇市场的交易员为抢先建仓而动价；承重条件是信用——说话不算数的央行，干预一次烧一次信号资本。<strong>订单流</strong>：央行订单触发私人跟单，Evans–Lyons 的订单流证据说明价格对订单流的反应远超公开信息含量；小单与反复逆风的小单最吃这条渠道。测度是老问题：多数央行滞后且部分披露干预数据，识别靠高频事件窗口与央行沟通文本的比对。</p><p><span class="marginnote">2022 年 9–10 月，日本财务省二十四年来首次买入口元，两轮合计动用逾 9 万亿日元；贬值势头此后才在美联储预期转向时放缓——方向性目标比波动率目标难守得多。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制收在目标的分野。<strong>降波动</strong>通常可达：逆风干预在急涨急跌时吸收流量，压低实现与隐含波动，这不需要改变均衡水平，只需中介功能在压力时缺位——第一课与上一课刚说明中介容量何时紧。<strong>守水平</strong>则撞基本面：储备是有限资源，对手是全球私人资产负债表；当汇率水平与政策基本面矛盾，第一代货币危机模型（Krugman 1979，见<a href="/econ/currency-crisis-models">货币危机模型</a>）给出剧本——投机者算得清储备耗尽的时刻，干预只是给时钟上弦；Obstfeld 与 Rogoff 1995 说得更直白：资本流动足够快时，钉住水平本身就是幻景。协调干预介于两者之间：1985 年广场协议时美元已高位，五国协同干预加政策转向，美元对日元两年内从 240 上下落到 130 上下；而无协调的小额干预常常只是噪声。退出是机制的镜子：瑞士国民银行 2011 年承诺 1.20 的瑞郎下限，敞口随欧元贬值压力累积，2015 年 1 月弃守，瑞郎盘中对欧元升值一度超过三成——水平承诺的代价是敞口无界。</p><p><span class="marginnote">水平承诺的账单有多大：瑞士国民银行为守 1.20 下限累积的外汇资产一度接近 GDP 的八成，折合每个瑞士人替央行背着六万多瑞郎的外币资产——先押注央行守不住的人可以等，央行却每多守一天就多买一天，敞口单向累积。</span></p>',6)),(e(),B(t,null,{default:a(()=>[o(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%86%B2%E9%94%80%E5%BC%8F%E5%B9%B2%E9%A2%84%22%5D%20--%3E%20PB%5B%22%E7%BB%84%E5%90%88%E5%B9%B3%E8%A1%A1%3A%20%E6%94%B9%E5%8F%98%E5%B8%81%E7%A7%8D%E4%BE%9B%E7%BB%99%22%5D%0A%20%20IN%20--%3E%20SG%5B%22%E4%BF%A1%E5%8F%B7%3A%20%E6%8A%AB%E9%9C%B2%E6%94%BF%E7%AD%96%E8%B7%AF%E5%BE%84%22%5D%0A%20%20IN%20--%3E%20OF%5B%22%E8%AE%A2%E5%8D%95%E6%B5%81%3A%20%E8%A7%A6%E5%8F%91%E7%A7%81%E4%BA%BA%E8%B7%9F%E5%8D%95%22%5D%0A%20%20PB%20--%3E%20PREM%5B%22%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%E8%B5%B0%E5%8A%A8%22%5D%0A%20%20SG%20--%3E%20EXP%5B%22%E9%A2%84%E6%9C%9F%E8%B7%AF%E5%BE%84%E9%87%8D%E4%BC%B0%22%5D%0A%20%20OF%20--%3E%20EXP%0A%20%20PREM%20--%3E%20FX%5B%22%E6%B1%87%E7%8E%87%22%5D%0A%20%20EXP%20--%3E%20FX%0A%20%20FX%20--%3E%7C%22%E6%B0%B4%E5%B9%B3%E6%92%9E%E5%9F%BA%E6%9C%AC%E9%9D%A2%22%7C%20RUN%5B%22%E5%82%A8%E5%A4%87%E8%80%97%E7%AB%AD%3A%20%E7%AC%AC%E4%B8%80%E4%BB%A3%E5%89%A7%E6%9C%AC%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>干预不替代宏观调整：它买时间或压波动，基本面矛盾只在财政与政策路径里解。发达国家汇率由利率预期主导，干预边际小——2022 年日本两轮逾 9 万亿日元也只算延缓。冲销有准财政成本：利差倒挂时，储备的收益低于冲销负债的利息，守汇率的账单按日计息。资格问题上一课已经见过：互换线是发达经济体的地板，无资格者用储备自我保险，这把储备需求接回主干课。最后一条边界是分工：干预管价格、花资产负债表；当涌入是持续流量而非瞬时波动，数量侧的工具——资本管制——是下一课。</p><p><span class="marginnote">初学者容易以为「储备越多越守得住汇率」，实际上储备是有限弹药而对手是全球私人资产负债表：投机者只需要在储备耗尽时刻之前集中下注。而且冲销本身有成本——储备赚的利息低于冲销债付的利息时，守汇率是一笔每天亏钱的生意。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>完全替代下冲销干预是空操作；溢价存在（第一课）是它有杠杆的前提。</li><li>三渠道：组合平衡动溢价、信号动预期、订单流动微观价格，承重条件各不相同。</li><li>降波动是可达目标；守水平撞基本面时是第一代危机剧本。</li><li>协调干预在 1985 年成事；瑞士 2015 年弃守说明水平承诺的敞口无界。</li><li>干预买时间不修基本面；持续流量问题交给数量侧工具。</li><li>出处：Friedman 1953；Dominguez–Frankel 1993；Sarno–Taylor, <em>JEL</em> 2001；Krugman, <em>JMCB</em> 1979；Obstfeld–Rogoff, <em>JEP</em> 1995；Evans–Lyons, <em>JPE</em> 2002。</li></ul>',5))])}const P=i(d,[["render",p]]);export{C as __pageData,P as default};
